import Accelerate
import Foundation

/// Stereo chorus: each channel reads a flat, preallocated delay line at a sinusoidally modulated
/// time around a fixed 15 ms center, the two channels' LFOs 90° apart (the classic trick that
/// gives chorus its width instead of just vibrato). The LFO is generated by a 2x2 rotation
/// recurrence (no per-sample `sin`/`cos`) and read with 4-point Catmull-Rom interpolation, which
/// tracks a moving fractional delay far more cleanly than linear interpolation (linear
/// interpolation low-pass filters the signal as the fractional part changes, audible as dulling
/// on a chorus's modulated top end).
///
/// `rate` and `depth` are smoothed (`FXSmoother`) so turning the knobs doesn't snap the LFO's
/// amplitude or speed; the LFO phase itself is always continuous.
final class ChorusNode: FXNode, @unchecked Sendable {
    private static let centerMs: Float = 15
    private static let maxDepthMs: Float = 10

    let kind: FXNodeKind = .chorus
    let specs = FXBuiltinSpecs.chorus
    let params: FXParamStore
    let meters = FXMeters()
    let latencySamples = 0

    private let sampleRate: Float
    private var lastGeneration: UInt32 = .max

    private var depthSmoother: FXSmoother
    private var mixSmoother: FXSmoother
    private var rateHz: Float = 0.8
    private var lfoRotCos: Float = 1
    private var lfoRotSin: Float = 0

    // LFO unit vectors, channel R 90 degrees ahead of L.
    private var lfoLCos: Float = 1, lfoLSin: Float = 0
    private var lfoRCos: Float = 0, lfoRSin: Float = 1

    private let bufferFrames: Int
    private let bufferMask: Int
    private let bufL: UnsafeMutablePointer<Float>
    private let bufR: UnsafeMutablePointer<Float>
    private var writeIndex = 0

    init(sampleRate: Float) {
        self.sampleRate = sampleRate
        params = FXParamStore(specs: FXBuiltinSpecs.chorus)
        depthSmoother = FXSmoother(initial: 1.5, timeMs: 50, sampleRate: sampleRate)
        mixSmoother = FXSmoother(initial: 0.3, timeMs: 20, sampleRate: sampleRate)
        let needed = Int(((Self.centerMs + Self.maxDepthMs) / 1000 * sampleRate).rounded(.up)) + 8
        bufferFrames = 1 << (Int.bitWidth - (needed - 1).leadingZeroBitCount)
        bufferMask = bufferFrames - 1
        bufL = .allocate(capacity: bufferFrames)
        bufR = .allocate(capacity: bufferFrames)
        bufL.initialize(repeating: 0, count: bufferFrames)
        bufR.initialize(repeating: 0, count: bufferFrames)
        setLFOIncrement(rateHz)
    }

    deinit {
        bufL.deallocate()
        bufR.deallocate()
    }

    private func setLFOIncrement(_ hz: Float) {
        let w = 2 * Float.pi * hz / sampleRate
        lfoRotCos = cosf(w)
        lfoRotSin = sinf(w)
    }

    private func refreshParams() {
        let gen = params.generation
        guard gen != lastGeneration else { return }
        lastGeneration = gen
        let newRate = params.get(0)
        if newRate != rateHz { rateHz = newRate; setLFOIncrement(rateHz) }
        depthSmoother.target = params.get(1)
        mixSmoother.target = params.get(2) / 100
    }

    func reset() {
        bufL.update(repeating: 0, count: bufferFrames)
        bufR.update(repeating: 0, count: bufferFrames)
        writeIndex = 0
        lfoLCos = 1; lfoLSin = 0
        lfoRCos = 0; lfoRSin = 1
        depthSmoother.snap()
        mixSmoother.snap()
    }

    /// Catmull-Rom interpolated read `delaySamples` behind the write head.
    @inline(__always) private func read(_ buf: UnsafeMutablePointer<Float>, delaySamples: Float) -> Float {
        let pos = Float(writeIndex) - delaySamples
        let i0 = Int(floor(pos))
        let frac = pos - Float(i0)
        let p0 = buf[(i0 - 1) & bufferMask]
        let p1 = buf[i0 & bufferMask]
        let p2 = buf[(i0 + 1) & bufferMask]
        let p3 = buf[(i0 + 2) & bufferMask]
        let a0 = -0.5 * p0 + 1.5 * p1 - 1.5 * p2 + 0.5 * p3
        let a1 = p0 - 2.5 * p1 + 2 * p2 - 0.5 * p3
        let a2 = -0.5 * p0 + 0.5 * p2
        let a3 = p1
        return ((a0 * frac + a1) * frac + a2) * frac + a3
    }

    func process(_ block: FXBlock) {
        refreshParams()
        meters.inputPeak = fxBlockPeak(block)
        let centerSamples = Self.centerMs / 1000 * sampleRate

        for i in 0..<block.frames {
            let l = block.left[i]
            let r = block.channels == 2 ? block.right[i] : l
            bufL[writeIndex] = l
            bufR[writeIndex] = r

            let depthMs = depthSmoother.next()
            let depthSamples = depthMs / 1000 * sampleRate
            let delayL = centerSamples + lfoLSin * depthSamples * 0.5
            let delayR = centerSamples + lfoRSin * depthSamples * 0.5
            let wetL = read(bufL, delaySamples: max(1, delayL))
            let wetR = read(bufR, delaySamples: max(1, delayR))

            // Rotate the LFO unit vectors by the per-sample increment (cos/sin addition
            // formula), i.e. advance the phase without calling `sinf`/`cosf` every sample.
            let nlc = lfoLCos * lfoRotCos - lfoLSin * lfoRotSin
            let nls = lfoLCos * lfoRotSin + lfoLSin * lfoRotCos
            lfoLCos = nlc; lfoLSin = fxFlush(nls)
            let nrc = lfoRCos * lfoRotCos - lfoRSin * lfoRotSin
            let nrs = lfoRCos * lfoRotSin + lfoRSin * lfoRotCos
            lfoRCos = nrc; lfoRSin = fxFlush(nrs)

            let mix = mixSmoother.next()
            block.left[i] = l * (1 - mix) + wetL * mix
            if block.channels == 2 { block.right[i] = r * (1 - mix) + wetR * mix }

            writeIndex = (writeIndex + 1) & bufferMask
        }
        meters.outputPeak = fxBlockPeak(block)
        meters.activity = mixSmoother.value
    }
}
